/* Six sequential scientific loops. Recorded evidence, with explicit scope. */
(() => {
 'use strict';
 const old=window.ResearchObservatory,D=window.OBSERVATORY_SIX,H=window.ResearchHub;
 if(!old||!D||!H)return;
 const accepted=()=>D.status==='accepted'&&D.loops_completed===6&&Array.isArray(D.solutions)&&D.solutions.length===6&&Array.isArray(D.gates)&&D.gates.length===6&&D.gates.every(g=>g?.status==='accepted');
 const e=H.escape,safe=H.safeURL;
 const list=x=>Array.isArray(x)?x.filter(v=>v!==null&&v!==undefined):[];
 const a=(r,t)=>`<a href="#research/${e(r)}">${e(t)}</a>`;
 const eq=x=>`<div class="hub-eq" aria-label="Mathematical statement">${e(x)}</div>`;
 const box=(t,b)=>`<section class="hub-panel"><h2>${e(t)}</h2>${b}</section>`;
 const title=(t,b)=>`<header class="hub-header"><p class="hub-kicker">Yang–Mills Workbench · Round17 · Six loops, three roles</p><h1>${e(t)}</h1><p class="hub-deck">${e(b)}</p></header>`;
 const table=(heads,rows)=>`<div class="hub-table-wrap"><table class="hub-table"><thead><tr>${heads.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const documents=D.documents&&typeof D.documents==='object'?D.documents:{};
 const doc=(k,t)=>Object.hasOwn(documents,k)?`<button data-r-doc="round17/${e(k)}">${e(t)}</button>`:'';
 const pages={home:'Research home','six-local':'A1 · Local operators','six-sparse':'A2 · Sparse gap','six-trial':'B1 · Physical trial','six-adjoint':'B2 · Added representation','six-graph':'C1 · New graph','six-kernel':'C2 · Channel experiment','six-team':'Team & roadmap','six-review':'Skeptic & reproduction'};
 function plot(key){const p=D.plots?.[key];if(!p||!Array.isArray(p.series)||!p.series.length||!p.series.every(s=>s&&Array.isArray(s.points)&&s.points.length&&s.points.every(q=>Array.isArray(q)&&q.length===2&&q.every(Number.isFinite))))return '<p role="status">Valid recorded data are unavailable.</p>';return old.chart(p.series,{title:p.title,xLabel:p.xLabel,yLabel:p.yLabel,zero:false})+`<p class="hub-plot-caption">${e(p.caption)}</p><a href="${safe(p.csv)}" download>Download plotted CSV</a>`;}
 function home(){if(!accepted())return title('Research evidence unavailable','The complete six-loop acceptance record is missing.');return title('Three goals, six completed research loops',D.summary)+
 box('What we established',table(['Loop','Detailed summary','Scope and evidence'],list(D.solutions).map(s=>[a(s.route,s.id+' · '+s.title),`<p>${e(s.plain)}</p>`+eq(s.equation),`<p>${e(s.limit)}</p>`+a(s.route,'Read derivation, critique and tests')])) )+
 box('How to use the workbench','<p>Read A1 before A2: the failed local bound explains the restricted support choice. Follow B1 into B2 to see how an added trial component repairs one insufficient finite bound. Follow C1 into C2 to distinguish the complete graph from its conditional central-link calculation. Each page has the contract, both researchers’ derivations, rejecting controls and saved data. Plots are recorded calculations; their CSV links give the inputs.</p>'+a('six-team','Explore the feedback network')+' · '+a('six-review','Reproduce all six loops'))+
 box('What remains open',`<p>${e(D.open)}</p>`+a('six-team','Inspect the next proof obligations'))+
 box('Previous results and learning tools',a('review16-home','Round16: two-cube action and physical scale')+' · '+a('review15-home','Round15: three-goal evidence')+' · '+a('variables','Einstein–QED branch')+' · <a href="#explore">Physics learning pages</a>');}
 function solution(route){if(!accepted())return '<p role="status">The complete acceptance record is unavailable.</p>';const s=list(D.solutions).find(x=>x.route===route);if(!s)return '<p role="status">No accepted result is available.</p>';return title(s.id+' · '+s.title,s.plain)+box('Precise result',eq(s.equation)+`<p>${e(s.limit)}</p>`)+(s.id==='C1'?box('The graph that is actually integrated','<img src="/six-four-cubes.svg" alt="Four cells share a central link. The outer boundary omits that link and four internal faces." style="width:100%;max-width:850px"/>'):'')+list(s.sections).map(p=>box(p.title,`<p>${e(p.text)}</p>`+(p.equation?eq(p.equation):''))).join('')+list(s.plots).map(k=>box(D.plots?.[k]?.title||'Recorded experiment',plot(k))).join('')+box('Independent critique and reproducible evidence',`<p>${e(s.review)}</p>`+doc(s.id.toLowerCase()+'-contract','Read the authorized contract')+doc(s.id.toLowerCase()+'-forward','Read the forward derivation')+doc(s.id.toLowerCase()+'-backward','Read the independent derivation')+doc(s.id.toLowerCase()+'-gate','Inspect the accepted source inventory'))+(s.next?box('Feedback selected the next step',`<p>${e(s.next)}</p>`):'');}
 function network(){const rows=list(D.stages);return `<img src="/six-collaboration.svg" alt="Forward and backward researchers report independently to the advisor through six accepted loops and two planning decisions." style="display:block;width:100%;max-width:900px;margin:auto"/><div role="img" aria-label="Two advisor decisions and six sequential research loops. Each loop compares forward and backward work before acceptance.">${table(['Stage','Forward work','Backward and skeptic work','Decision'],rows.map(r=>[e(r.stage),e(r.forward),e(r.backward),e(r.decision)]))}</div><p>The two researchers report separately to the advisor–skeptic. Each second loop starts after its first gate. Goals B and C were revised after both Goal A loops.</p>`;}
 function team(){return title('The roadmap changes when a check fails','Three scientific roles completed six loops, with an initial plan and a second advisory decision after Goal A. These are completed collaboration stages.')+box('Eight-stage collaboration record',network())+box('Feedback that changed the work',table(['Finding','Decision','Remaining limit'],list(D.feedback).map(r=>[e(r.finding),e(r.decision),e(r.limit)]))+doc('feedback','Read the decision ledger'))+box('Bidirectional dependency routes',table(['Target','Status','Reviewed rule count'],list(D.routes).map(r=>[e(r.target),e(r.status),e(String(r.steps??'—'))]))+'<p>The planner searches a finite library of reviewed implications in both directions. Its certificate is replayed separately. It does not invent missing premises or constitute a formal proof kernel.</p>'+doc('proof','Inspect actual routes and blocked obligations'))+box('Next three goals',table(['Goal','Forward experiment','Backward requirement','Failure test'],list(D.next).map(r=>[e(r.goal),e(r.forward),e(r.backward),e(r.gate)]))+doc('roadmap','Read the next roadmap'))+box('Variable register',table(['Symbol or choice','Meaning','What it does not establish'],list(D.variables).map(r=>[e(r.symbol),e(r.meaning),e(r.limit)])) );}
 function review(){return title('What the skeptic accepted—and what is still insufficient','Exact finite arithmetic, conventional mathematical proofs, implementation checks and physical applicability have separate evidence.')+box('Six loop gates',table(['Loop','Forward checks','Independent checks','Comparison checks','Scope'],list(D.gates).map(r=>[e(r.loop.toUpperCase()),e(String(r.producer_checks)),e(String(r.independent_checks)),e(String(r.comparison_checks)),e(r.scope)])))+box('Corrections and rejecting controls',table(['Finding','Repair or consequence','Limit'],list(D.feedback).map(r=>[e(r.finding),e(r.decision),e(r.limit)])))+box('Run the work locally',eq('python3 start.py\n# Open http://127.0.0.1:8001/\npython3 research/round17/reproduce.py --output /absolute/path/to/new-results\npython3 research/round17/proof_routes.py --output /absolute/path/to/new-proof.json')+doc('readme','Read all launch and reproduction instructions')+doc('report','Read the complete six-result dossier')+'<p><a href="/research-round17.zip" download>Download the complete six-loop package</a> · <a href="https://github.com/occult-kranti/yang_mills_workbench">Open the GitHub repository</a></p>')+box('Sources and verification limits',doc('sources','Read the primary-source applicability audit')+`<p>${e(D.verification)}</p><p>These are agent critiques, not credentialed human peer review. Real-browser visual layout and keyboard testing remain unverified.</p>`);}
 const registry=window.OBSERVATORY_RESEARCH?.documents;if(registry&&typeof registry==='object')for(const [k,v]of Object.entries(documents))if(/^[a-zA-Z][a-zA-Z0-9_-]*$/.test(k))registry['round17/'+k]=v;
 function render(route='home'){if(route==='review16-home')return `<p class="hub-limit">Historical Round16 snapshot. ${a('home','Current six-loop research')}</p>`+old.render('home');if(!Object.hasOwn(pages,route))return old.render(route);const body=route==='home'?home():route==='six-team'?team():route==='six-review'?review():solution(route);return `<div class="research-shell hub m8"><nav class="hub-nav" aria-label="Six-loop research navigation">${Object.entries(pages).map(([r,t])=>`<a href="#research/${r}" ${r===route?'aria-current="page"':''}>${e(t)}</a>`).join('')}</nav>${body}<footer class="hub-foot"><a href="/research-round17.zip" download>Download six-loop evidence</a> · ${a('review16-home','Previous research snapshot')} · <a href="https://occult-kranti.github.io/yang_mills_workbench/#research">Published workbench</a></footer></div>`;}
 window.ResearchSix={render,plot,network};window.ResearchObservatory={...old,render,afterRender(){const r=location.hash.split('/')[1]||'home';if(Object.hasOwn(pages,r))document.title=pages[r]+' · Yang–Mills Workbench';else old.afterRender();}};
})();
